'use client';

import { FlowDiagram } from '@diax/react';
import {
  Cloud,
  HardDrive,
  type LucideIcon,
  RefreshCw,
  Server,
  Zap,
} from 'lucide-react';

const DecisionNode = ({
  icon: Icon,
  title,
  type,
}: {
  icon: LucideIcon;
  title: string;
  type: 'question' | 'yes' | 'no' | 'result';
}) => {
  const styles = {
    question:
      'border-[#5E6AD2]/40 bg-[#5E6AD2]/10 text-[#5E6AD2] shadow-[#5E6AD2]/10',
    yes: 'border-emerald-500/40 bg-emerald-500/10 text-emerald-400',
    no: 'border-amber-500/40 bg-amber-500/10 text-amber-400',
    result: 'border-white/10 bg-white/5 text-white/80',
  };

  return (
    <div
      className={`flex items-center gap-3 rounded-xl border px-5 py-3.5 backdrop-blur-md shadow-lg transition-all ${styles[type]}`}
    >
      <Icon className="h-4.5 w-4.5 shrink-0" />
      <span className="text-sm font-medium whitespace-nowrap">{title}</span>
    </div>
  );
};

export default function DecisionTree() {
  return (
    <FlowDiagram
      nodes={[
        {
          id: 'start',
          content: (
            <DecisionNode
              icon={Zap}
              title="Need real-time sync?"
              type="question"
            />
          ),
        },
        {
          id: 'yes-rt',
          content: (
            <DecisionNode
              icon={RefreshCw}
              title="High write volume?"
              type="question"
            />
          ),
        },
        {
          id: 'no-rt',
          content: (
            <DecisionNode
              icon={Server}
              title="Need offline support?"
              type="question"
            />
          ),
        },
        {
          id: 'firestore',
          content: <DecisionNode icon={Cloud} title="Firestore" type="yes" />,
        },
        {
          id: 'supabase',
          content: (
            <DecisionNode icon={Server} title="Supabase Realtime" type="yes" />
          ),
        },
        {
          id: 'sqlite',
          content: (
            <DecisionNode
              icon={HardDrive}
              title="SQLite + Sync"
              type="result"
            />
          ),
        },
        {
          id: 'postgres',
          content: <DecisionNode icon={Server} title="PostgreSQL" type="no" />,
        },
      ]}
      relations={[
        'start->|Yes|yes-rt',
        'start->|No|no-rt',
        'yes-rt->|No|firestore',
        'yes-rt->|Yes|supabase',
        'no-rt->|Yes|sqlite',
        'no-rt->|No|postgres',
      ]}
      direction="vertical"
      density="spacious"
      centered
      stagger
      highlightOnHover
    />
  );
}
